import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"越调·凭阑人暮春即事二首","description":"","frontmatter":{"title":"越调·凭阑人暮春即事二首","date":"2026-11-11T00:00:00.000Z","seq":37,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/越调·凭阑人暮春即事二首.md","filePath":"blogs/元曲·张可久/越调·凭阑人暮春即事二首.md"}'),o={name:"blogs/元曲·张可久/越调·凭阑人暮春即事二首.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="越调·凭阑人暮春即事二首" tabindex="-1">越调·凭阑人暮春即事二首 <a class="header-anchor" href="#越调·凭阑人暮春即事二首" aria-label="Permalink to &quot;越调·凭阑人暮春即事二首&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">万朵青山生暮云，数点红香留晚春。</p><p class="poem-stanza">凭阑愁玉人，对花宽翠裙。</p><p class="poem-stanza">小玉阑干月半掐，嫩绿池塘春几家。</p><p class="poem-stanza">鸟啼芳树丫，燕衔黄柳花。</p><p class="poem-stanza">江楼即事一曲琵琶江上舟，十二阑干天外楼。</p><p class="poem-stanza">粉香蝶也愁，玉容花见羞。</p><p class="poem-stanza">八咏楼上酬正则李侯烂醉东君三月时，细和休文八韵诗。</p><p class="poem-stanza">舞裙催《柘枝》，曲阑摇柳丝。</p><p class="poem-stanza">秋思和吴克斋一寸冰蟾明翠廊，万里青天书雁行。</p><p class="poem-stanza">碧梧敲晚凉，玉人烧夜香。</p><p class="poem-stanza">和白玉真人宝剑英雄血已干，玉府神仙心自闲。</p><p class="poem-stanza">炼霞成大丹，袖云归故山。</p><p class="poem-stanza">玉手携香罗帕干，粉面粘花妆镜寒。</p><p class="poem-stanza">对楼千万山，倚云十二鬟。</p><p class="poem-stanza">湖上醉余二首明月中流歌扣舷，柔雪双娃同采莲。</p><p class="poem-stanza">小词玉翼蝉，醉书金粉笺。</p><p class="poem-stanza">屏外氤氲兰麝飘，帘底星松鹦鹉娇。</p><p class="poem-stanza">暖香绣玉腰，小花金步摇。</p><p class="poem-stanza">席上分题妆淡亭亭堆髻螺，歌缓盈盈停眼波。</p><p class="poem-stanza">念奴留意多，使君如醉何？晚晴小景金羽翩翩柳外莺，玉手纤纤膝上筝。</p><p class="poem-stanza">晚风花雨晴，小楼山月明。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
